			t.Fatal(err)
		}
		if err := os.Chmod(p, 0o000); err != nil {
			t.Fatal(err)
		}
		if _, err := Open(dir); err == nil {
			t.Fatal("unreadable record must fail Open")
		}
		_ = os.Chmod(p, 0o600) // 便于 TempDir 清理
	})
}

