	// 作业号读取与按提交人列举都不再返回残留的总和、平方和、日志、输入摘要、
	// 结果摘要或校验值。作业号、提交人、请求号、原始整数及次序、种子、有序
	// 依赖与已有时间均不在此改动；原始整数序列属于提交参数，即使为空也原样
	// 保留，不补造参数。没有残留的记录不触发改写；无法解析、版本不支持等
	// 打开错误在此阶段之前就已返回，损坏记录不会借此被当成正常记录接受。
	if j.status == StatusFailed || j.status == StatusCanceled {
		sanitizeResidualSuccessArtifacts(dir, j)
	}
	// 排队记录的残留成功产物清理放在第二趟升序扫描：依赖列表重复/先后关系
	// 非法、原始序列为空等记录自身有误的排队作业在那里由 failRestoredJob
	// 改判失败（同样清除产物）；通过自身检查、仍合法排队的记录才只清残留、
	// 保持排队，避免让调用方在它真正完成前读到旧归档。
	if j.status == StatusRunning {
		failRestoredJob(dir, j, "计算被中断：归档上次关闭时作业仍在运行", 0)
	}
	if j.status == StatusSucceeded {
		// 除完整性外，还必须满足三条独立的对应/复算规则：
		//  0. 依赖列表自身合法：与排队记录复查共用同一个入口
		//     invalidDependencyListReason（先查重复引用、再查先后关系，
		//     规则与措辞见 blocker.go）。旧版本或被改动的记录可能保存了
		//     重复引用或不小于本作业号的上游，此时即使追加值、总和、
		//     平方和、摘要、日志与校验值全部自洽，也不能当作合法成功
		//     归档（重复引用会把同一上游总和追加两次；引用自己或后来
		//     作业不可能通过提交校验）。这属于本作业记录自身有误，在
		//     任何上游可用性核对之前判定，BlockerID 为 0，不把被引用
		//     的有效上游判成失败。
